// Dependency-free WebGL / WebXR memory gallery. No external requests.
export function perspective(fovy,aspect,near=.05,far=100){const f=1/Math.tan(fovy/2);return new Float32Array([f/aspect,0,0,0,0,f,0,0,0,0,(far+near)/(near-far),-1,0,0,2*far*near/(near-far),0]);}
export function viewMatrix(yaw,pitch){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);return new Float32Array([cy,sp*sy,cp*sy,0,0,cp,-sp,0,-sy,sp*cy,cp*cy,0,0,-1.6*cp,1.6*sp,1]);}
export function memoryPosition(i,n){const a=(i-(n-1)/2)*Math.min(.65,5.1/Math.max(n,1));return {x:Math.sin(a)*3,y:1.65,z:-Math.cos(a)*3,angle:a};}
export class MemoryGarden{
 constructor(canvas,items,{scene='room',onChange=()=>{}}={}){this.canvas=canvas;this.items=items;this.scene=scene;this.onChange=onChange;this.yaw=0;this.pitch=0;this.index=0;this.urls=[];this.textures=[];this.stopped=false;this.drag=null;const gl=canvas.getContext('webgl',{xrCompatible:true,alpha:false,antialias:true});if(!gl)throw Error('This browser does not support WebGL. Please try another browser.');this.gl=gl;this.program=this.createProgram();this.position=gl.getAttribLocation(this.program,'aPosition');this.uv=gl.getAttribLocation(this.program,'aUV');this.uProjection=gl.getUniformLocation(this.program,'uProjection');this.uView=gl.getUniformLocation(this.program,'uView');this.uModel=gl.getUniformLocation(this.program,'uModel');this.uTint=gl.getUniformLocation(this.program,'uTint');this.uUse=gl.getUniformLocation(this.program,'uUse');this.buffer=gl.createBuffer();this.handlers=[];this.prepare();this.bind();this.focus(0);this.frame=requestAnimationFrame(()=>this.desktop());}
 createProgram(){const gl=this.gl;const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};const v=shader(gl.VERTEX_SHADER,`attribute vec3 aPosition;attribute vec2 aUV;uniform mat4 uProjection,uView,uModel;varying vec2 vUV;void main(){vUV=aUV;gl_Position=uProjection*uView*uModel*vec4(aPosition,1.);}`);const f=shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec2 vUV;uniform sampler2D uTexture;uniform vec4 uTint;uniform bool uUse;void main(){gl_FragColor=uUse?texture2D(uTexture,vUV)*uTint:uTint;}`);const p=gl.createProgram();gl.attachShader(p,v);gl.attachShader(p,f);gl.linkProgram(p);gl.deleteShader(v);gl.deleteShader(f);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error('Unable to initialize memory garden.');return p;}
 prepare(){const gl=this.gl;const quad=[-.5,-.5,0,0,1,.5,-.5,0,1,1,.5,.5,0,1,0,-.5,-.5,0,0,1,.5,.5,0,1,0,-.5,.5,0,0,0];gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(quad),gl.STATIC_DRAW);this.items.forEach(m=>{const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([167,155,183,255]));gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);const image=new Image();image.onload=()=>{if(this.stopped)return;gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);};if(m.blob?.type.startsWith('image/')){const u=URL.createObjectURL(m.blob);this.urls.push(u);image.src=u;}else image.src='./assets/room.jpg';this.textures.push(texture);});}
 bind(){const on=(target,name,fn)=>{target.addEventListener(name,fn);this.handlers.push(()=>target.removeEventListener(name,fn));};on(this.canvas,'pointerdown',e=>{this.drag={x:e.clientX,y:e.clientY};this.canvas.setPointerCapture(e.pointerId);});on(this.canvas,'pointermove',e=>{if(!this.drag)return;this.yaw+=(e.clientX-this.drag.x)*.004;this.pitch=Math.max(-.6,Math.min(.6,this.pitch+(e.clientY-this.drag.y)*.003));this.drag={x:e.clientX,y:e.clientY};});on(this.canvas,'pointerup',()=>this.drag=null);on(this.canvas,'pointercancel',()=>this.drag=null);on(window,'keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();this.focus(this.index-1);}if(e.key==='ArrowRight'){e.preventDefault();this.focus(this.index+1);}});}
 focus(i){this.index=(i+this.items.length)%this.items.length;const p=memoryPosition(this.index,this.items.length);this.yaw=-p.angle;this.onChange(this.items[this.index],this.index);}
 model(x,y,z,w,h,a=0){const c=Math.cos(a),s=Math.sin(a);return new Float32Array([c*w,0,-s*w,0,0,h,0,0,s,0,c,0,x,y,z,1]);}
 draw(projection,view){const gl=this.gl;gl.enable(gl.DEPTH_TEST);const color=this.scene==='dusk'?[.16,.13,.23,1]:this.scene==='lake'?[.30,.35,.39,1]:[.34,.29,.34,1];gl.clearColor(...color);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);gl.enableVertexAttribArray(this.position);gl.vertexAttribPointer(this.position,3,gl.FLOAT,false,20,0);gl.enableVertexAttribArray(this.uv);gl.vertexAttribPointer(this.uv,2,gl.FLOAT,false,20,12);gl.uniformMatrix4fv(this.uProjection,false,projection);gl.uniformMatrix4fv(this.uView,false,view);const plane=(model,tint,texture)=>{gl.uniformMatrix4fv(this.uModel,false,model);gl.uniform4fv(this.uTint,tint);gl.uniform1i(this.uUse,texture?1:0);if(texture)gl.bindTexture(gl.TEXTURE_2D,texture);gl.drawArrays(gl.TRIANGLES,0,6);};for(let i=0;i<this.items.length;i++){const p=memoryPosition(i,this.items.length);plane(this.model(p.x,p.y,p.z,1.72,1.32,-p.angle),[.9,.85,.79,1]);plane(this.model(p.x-Math.sin(p.angle)*.02,p.y+.04,p.z+Math.cos(p.angle)*.02,1.57,1.08,-p.angle),[1,1,1,1],this.textures[i]);}
 // A ring of softly colored, static markers anchors scale without forced locomotion.
 for(let i=0;i<40;i++){const a=i/40*Math.PI*2;plane(this.model(Math.sin(a)*5,.12,-Math.cos(a)*5,.08,.24,-a),[.73,.65,.8,1]);}}
 desktop(){if(this.stopped||this.session)return;const c=this.canvas;const ratio=Math.min(devicePixelRatio||1,2);if(c.width!==Math.floor(c.clientWidth*ratio)||c.height!==Math.floor(c.clientHeight*ratio)){c.width=c.clientWidth*ratio;c.height=c.clientHeight*ratio;}this.gl.bindFramebuffer(this.gl.FRAMEBUFFER,null);this.gl.viewport(0,0,c.width,c.height);this.draw(perspective(Math.PI/3,c.width/c.height),viewMatrix(this.yaw,this.pitch));this.frame=requestAnimationFrame(()=>this.desktop());}
 async enterXR(){if(!navigator.xr||!await navigator.xr.isSessionSupported('immersive-vr'))throw Error('VR is not available here. Open this HTTPS page in a compatible headset browser; you can still explore by dragging.');const session=await navigator.xr.requestSession('immersive-vr',{optionalFeatures:['local-floor']});this.session=session;try{await this.gl.makeXRCompatible();session.updateRenderState({baseLayer:new XRWebGLLayer(session,this.gl)});let space;try{space=await session.requestReferenceSpace('local-floor');}catch{space=await session.requestReferenceSpace('local');}session.addEventListener('select',()=>this.focus(this.index+1));session.addEventListener('end',()=>{this.session=null;if(!this.stopped)this.frame=requestAnimationFrame(()=>this.desktop());},{once:true});const frame=(time,f)=>{if(this.stopped)return;const pose=f.getViewerPose(space);if(pose){const layer=session.renderState.baseLayer;this.gl.bindFramebuffer(this.gl.FRAMEBUFFER,layer.framebuffer);this.gl.enable(this.gl.SCISSOR_TEST);for(const view of pose.views){const v=layer.getViewport(view);this.gl.viewport(v.x,v.y,v.width,v.height);this.gl.scissor(v.x,v.y,v.width,v.height);this.draw(view.projectionMatrix,view.transform.inverse.matrix);}this.gl.disable(this.gl.SCISSOR_TEST);}session.requestAnimationFrame(frame);};cancelAnimationFrame(this.frame);session.requestAnimationFrame(frame);}catch(e){await session.end();this.session=null;throw e;}}
 async dispose(){this.stopped=true;cancelAnimationFrame(this.frame);if(this.session)await this.session.end();this.handlers.forEach(fn=>fn());this.urls.forEach(u=>URL.revokeObjectURL(u));this.textures.forEach(t=>this.gl.deleteTexture(t));this.gl.deleteBuffer(this.buffer);this.gl.deleteProgram(this.program);}
}

// Screen-only fallback for browsers without a GPU/WebGL context.
export class FallbackGarden{
 constructor(canvas,items,{onChange=()=>{}}={}){this.canvas=canvas;this.items=items;this.index=0;this.onChange=onChange;this.urls=[];canvas.hidden=true;canvas.style.display='none';this.stage=document.createElement('div');this.stage.className='fallback-stage';this.stage.setAttribute('aria-label','Screen-only memory gallery');canvas.after(this.stage);this.focus(0);this.key=e=>{if(e.key==='ArrowLeft')this.focus(this.index-1);if(e.key==='ArrowRight')this.focus(this.index+1);};window.addEventListener('keydown',this.key);this.down=e=>this.x=e.clientX;this.up=e=>{if(this.x!==undefined&&Math.abs(e.clientX-this.x)>40)this.focus(this.index+(e.clientX<this.x?1:-1));this.x=undefined;};this.stage.addEventListener('pointerdown',this.down);this.stage.addEventListener('pointerup',this.up);}
 focus(i){this.index=(i+this.items.length)%this.items.length;this.urls.forEach(u=>URL.revokeObjectURL(u));this.urls=[];this.stage.replaceChildren();const m=this.items[this.index];const card=document.createElement('div');card.className='fallback-memory';if(m.blob?.type.startsWith('image/')||m.asset){const img=document.createElement('img');const u=m.blob?URL.createObjectURL(m.blob):m.asset;if(m.blob)this.urls.push(u);img.src=u;img.alt=m.title;card.append(img);}else{const story=document.createElement('p');story.textContent=m.story||m.title;card.append(story);}const label=document.createElement('p');label.className='fallback-label';label.textContent=m.title;card.append(label);this.stage.append(card);this.onChange(m,this.index);}
 async enterXR(){throw Error('This browser cannot render VR. Open the HTTPS version in a WebXR-compatible headset browser.');}
 async dispose(){window.removeEventListener('keydown',this.key);this.urls.forEach(u=>URL.revokeObjectURL(u));this.stage.remove();this.canvas.hidden=false;this.canvas.style.display='';}
}
